// 1) El estado: una variable. Es la única fuente de verdad.
let tareas = [
  { id: 1, texto: "Contar pallets del muelle 3", hecha: false },
  { id: 2, texto: "Etiquetar bultos de Rosario", hecha: true },
];
let proximoId = 3;

// 2) El render manual: borra la lista y la vuelve a armar desde el estado.
const lista = document.querySelector("#lista");
const resumen = document.querySelector("#resumen");

function render() {
  lista.innerHTML = "";
  for (const t of tareas) {
    const li = document.createElement("li");
    li.dataset.id = t.id;
    li.className = t.hecha ? "hecha" : "";
    li.innerHTML = `<input type="checkbox" ${t.hecha ? "checked" : ""}>
      <span>${t.texto}</span> <button class="borrar">x</button>`;
    lista.append(li);
  }
  const pendientes = tareas.filter(t => !t.hecha).length;
  resumen.textContent = `Pendientes: ${pendientes} de ${tareas.length}`;
}

// 3) Los cambios tocan el estado y después llaman a render().
document.querySelector("#alta").addEventListener("submit", (e) => {
  e.preventDefault();
  const input = document.querySelector("#texto");
  const texto = input.value.trim();
  if (!texto) return;
  tareas.push({ id: proximoId++, texto, hecha: false });
  input.value = "";
  render();
});

lista.addEventListener("click", (e) => {
  const li = e.target.closest("li");
  if (!li) return;
  const id = Number(li.dataset.id);
  if (e.target.matches(".borrar")) tareas = tareas.filter(t => t.id !== id);
  if (e.target.matches("input[type=checkbox]")) {
    const t = tareas.find(t => t.id === id);
    t.hecha = !t.hecha;
  }
  render();
});

render();   // primer dibujo, con el estado inicial

